import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(0.8, 0.32);

  // Load the ceramic grain texture
  let textureAsset = null;
  const materialPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        textureAsset = tex;
        tex.flipY = false;
        return tex;
      })
    : Promise.resolve(null);

  // Create material with texture node
  const mat = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
  });

  // Update material when texture loads
  materialPromise.then((tex) => {
    if (tex) {
      const texNode = texture(tex);
      mat.colorNode = texNode;
    } else {
      mat.colorNode = vec3(0.06); // fallback to surface color #0b0b10
    }
  });

  const plane = new THREE.Mesh(geometry, mat);
  plane.position.copy(new THREE.Vector3(
    config.scenePosition?.[0] ?? 1.25,
    config.scenePosition?.[1] ?? 0.7,
    config.scenePosition?.[2] ?? 0
  ));

  if (config.sceneRotation) {
    plane.rotation.set(...config.sceneRotation);
  }
  if (config.sceneScale) {
    plane.scale.set(...config.sceneScale);
  }

  // ============================================================================
  // 2. ACCENT EDGE LIGHT (rim to highlight the capsule)
  // ============================================================================
  const rimLight = new THREE.PointLight(0xff2a38, 0.8, 3.0);
  rimLight.position.set(0.6, 0.3, 0.8);
  plane.add(rimLight);

  // ============================================================================
  // 3. INTERACTION STATE & ANIMATIONS
  // ============================================================================
  let isHovered = false;
  let hoverTimeline = null;
  let clickTimeline = null;

  const handlers = {
    pointerenter: () => {
      if (isHovered) return;
      isHovered = true;

      // Kill any existing hover timeline
      if (hoverTimeline) hoverTimeline.kill();

      // rise-in: subtle lift (0.15 scene units), power3.out, 0.7s
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(plane.position, {
        y: plane.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },

    pointerleave: () => {
      if (!isHovered) return;
      isHovered = false;

      // Kill existing hover timeline
      if (hoverTimeline) hoverTimeline.kill();

      // Return to original position
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(plane.position, {
        y: config.scenePosition?.[1] ?? 0.7,
        duration: 0.5,
        ease: 'power2.out',
      });
    },

    click: () => {
      // press-down: scale 0.97, 120ms, back.out
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.timeline();
      clickTimeline.to(plane.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      clickTimeline.to(plane.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power2.out',
      });

      // Emit navigation event
      ctx.emit('hub-pricing.select', {});
    },
  };

  plane.userData.handlers = handlers;

  // ============================================================================
  // 4. CLEANUP
  // ============================================================================
  plane.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    geometry.dispose();
    mat.dispose();
    if (textureAsset) textureAsset.dispose();
    rimLight.dispose();
  };

  return plane;
}
